const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Control setup
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Cinematic lighting: Key-Fill-Rim with ambient base
const keyLight = new THREE.DirectionalLight(0xfff4e6, 1.35);
keyLight.position.set(8, 12, 6);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 60;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xcce6ff, 0.55);
fillLight.position.set(-8, 6, 4);

const rimLight = new THREE.SpotLight(0xff8c69, 0.85);
rimLight.position.set(-5, 8, -6);
rimLight.lookAt(0, 0, 0);
rimLight.penumbra = 0.4;

const ambientLight = new THREE.AmbientLight(0x7f8aa6, 0.35);
scene.add(ambientLight, keyLight, fillLight, rimLight);

// Atmospheric depth
scene.fog = new THREE.Fog(0xf4f7fb, 8, 45);

// Olympus Mountain - massive layered rock structure
const olympusGroup = new THREE.Group();
scene.add(olympusGroup);

// Primary mountain geometry with vertex displacement for rocky detail
const mountainGeo = new THREE.CylinderGeometry(2.5, 9, 35, 16, 12);
const posAttribute = mountainGeo.attributes.position;
for (let i = 0; i < posAttribute.count; i++) {
    const x = posAttribute.getX(i);
    const y = posAttribute.getY(i);
    const z = posAttribute.getZ(i);
    const noise = Math.sin(x * 0.8) * Math.cos(y * 0.4) * 0.6 + Math.cos(z * 0.6) * 0.4;
    const jitter = (Math.random() - 0.5) * 0.15;
    const scale = 1 + (noise + jitter) * 0.15;
    posAttribute.setX(i, x * scale);
    posAttribute.setZ(i, z * scale);
}
posAttribute.needsUpdate = true;
mountainGeo.computeVertexNormals();

const rockMaterial = new THREE.MeshStandardMaterial({
    color: 0x7a8fa3,
    roughness: 0.92,
    metalness: 0.05,
    flatShading: true
});
const mountain = new THREE.Mesh(mountainGeo, rockMaterial);
mountain.position.y = -12;
mountain.receiveShadow = true;
mountain.castShadow = true;
olympusGroup.add(mountain);

// Snow-capped peak
const peakGeo = new THREE.ConeGeometry(2.8, 8, 12);
const snowMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.8,
    metalness: 0.0
});
const peak = new THREE.Mesh(peakGeo, snowMaterial);
peak.position.y = 15.5;
peak.castShadow = true;
peak.receiveShadow = true;
olympusGroup.add(peak);

// Cloud layers floating at different altitudes
function createCloudRing(radius, yPos, count, turbulence) {
    const group = new THREE.Group();
    const geo = new THREE.SphereGeometry(1, 16, 16);
    const mat = new THREE.MeshStandardMaterial({
        color: 0xffffff,
        transparent: true,
        opacity: 0.35,
        roughness: 1
    });

    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const mesh = new THREE.Mesh(geo, mat);
        const r = radius + Math.sin(i * 1.5) * turbulence;
        mesh.position.set(
            Math.cos(angle) * r,
            yPos + Math.sin(i * 2.3) * 0.8,
            Math.sin(angle) * r
        );
        mesh.scale.setScalar(1.5 + Math.random() * 1.2);
        group.add(mesh);
    }
    return group;
}

const cloudsLow = createCloudRing(6, 2, 10, 0.8);
const cloudsHigh = createCloudRing(5.5, 10, 8, 0.5);
scene.add(cloudsLow, cloudsHigh);

// Kratos Character Construction (Procedural stylized warrior)
const kratosGroup = new THREE.Group();
scene.add(kratosGroup);

// Materials
const skinMat = new THREE.MeshStandardMaterial({
    color: 0xd4d3c8,
    roughness: 0.65,
    metalness: 0.0
});

const tattooMat = new THREE.MeshStandardMaterial({
    color: 0xd4d3c8,
    roughness: 0.65,
    emissive: 0x8b0000,
    emissiveIntensity: 0.15
});

const armorMat = new THREE.MeshStandardMaterial({
    color: 0x3a3a3a,
    roughness: 0.4,
    metalness: 0.75
});

const leatherMat = new THREE.MeshStandardMaterial({
    color: 0x8b4513,
    roughness: 0.95,
    metalness: 0.0
});

const redClothMat = new THREE.MeshStandardMaterial({
    color: 0x6b0000,
    roughness: 0.9,
    metalness: 0.0,
    side: THREE.DoubleSide
});

// Torso (muscular build with tattooed skin)
const torsoGeo = new THREE.BoxGeometry(0.9, 1.3, 0.55);
const torso = new THREE.Mesh(torsoGeo, tattooMat);
torso.position.y = 0;
torso.castShadow = true;
kratosGroup.add(torso);

// Armor skirt (leather/ bronze)
const skirtGeo = new THREE.CylinderGeometry(0.45, 0.65, 0.7, 8);
const skirt = new THREE.Mesh(skirtGeo, armorMat);
skirt.position.y = -0.7;
skirt.castShadow = true;
kratosGroup.add(skirt);

// Red loincloth/cape geometry with vertex wave for wind
const capeGeo = new THREE.PlaneGeometry(0.9, 2.2, 6, 10);
const cape = new THREE.Mesh(capeGeo, redClothMat);
cape.position.set(0, -0.2, -0.35);
cape.rotation.x = 0.15;
kratosGroup.add(cape);

// Head (bald with goatee suggestion)
const headGeo = new THREE.BoxGeometry(0.38, 0.42, 0.38);
const head = new THREE.Mesh(headGeo, skinMat);
head.position.y = 1.0;
head.castShadow = true;
kratosGroup.add(head);

const craniumGeo = new THREE.SphereGeometry(0.2, 16, 16);
const cranium = new THREE.Mesh(craniumGeo, skinMat);
cranium.position.y = 1.15;
kratosGroup.add(cranium);

// Limb construction with articulation points
function createLimb(type, isLeft, material) {
    const group = new THREE.Group();
    const side = isLeft ? 1 : -1;

    if (type === 'arm') {
        // Shoulder joint
        const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.22, 16, 16), material);
        group.add(shoulder);

        // Upper arm (muscular)
        const upperArm = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.12, 0.65, 12), material);
        upperArm.position.y = -0.325;
        upperArm.castShadow = true;
        group.add(upperArm);

        // Forearm (tattooed) with bracer
        const forearmGroup = new THREE.Group();
        forearmGroup.position.y = -0.65;

        const forearm = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.09, 0.6, 12), tattooMat);
        forearm.position.y = -0.3;
        forearm.castShadow = true;
        forearmGroup.add(forearm);

        // Bracer
        const bracer = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.12, 0.3, 12), armorMat);
        bracer.position.y = -0.35;
        bracer.castShadow = true;
        forearmGroup.add(bracer);

        // Hand
        const hand = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.18, 0.18), skinMat);
        hand.position.y = -0.7;
        hand.castShadow = true;
        forearmGroup.add(hand);

        group.add(forearmGroup);
        group.position.set(side * 0.55, 0.6, 0);

        return { root: group, forearm: forearmGroup, hand: hand };
    } else { // leg
        // Thigh
        const thigh = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.16, 0.75, 12), skinMat);
        thigh.position.y = -0.375;
        thigh.castShadow = true;
        group.add(thigh);

        // Shin with greaves
        const shin = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.12, 0.75, 12), armorMat);
        shin.position.y = -0.9;
        shin.castShadow = true;
        group.add(shin);

        // Foot
        const foot = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.15, 0.3), armorMat);
        foot.position.set(0, -1.35, 0.05);
        group.add(foot);

        group.position.set(side * 0.3, -1.0, 0);
        return group;
    }
}

const leftArm = createLimb('arm', true, skinMat);
const rightArm = createLimb('arm', false, skinMat);
const leftLeg = createLimb('leg', true, skinMat);
const rightLeg = createLimb('leg', false, skinMat);

kratosGroup.add(leftArm.root);
kratosGroup.add(rightArm.root);
kratosGroup.add(leftLeg);
kratosGroup.add(rightLeg);

// Blades of Chaos (wrist blades with glowing embers)
function createBlade() {
    const bladeGroup = new THREE.Group();

    // Chain links
    for (let i = 0; i < 10; i++) {
        const link = new THREE.Mesh(
            new THREE.TorusGeometry(0.035, 0.012, 8, 16),
            new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.9, roughness: 0.3 })
        );
        link.position.y = -i * 0.07;
        link.rotation.y = (i % 2) * Math.PI / 2;
        bladeGroup.add(link);
    }

    // Flame blade
    const blade = new THREE.Mesh(
        new THREE.ConeGeometry(0.07, 0.8, 4),
        new THREE.MeshStandardMaterial({
            color: 0x2a2a2a,
            emissive: 0xff4400,
            emissiveIntensity: 0.6,
            roughness: 0.4,
            metalness: 0.8
        })
    );
    blade.position.y = -0.9;
    bladeGroup.add(blade);

    return bladeGroup;
}

const leftBlade = createBlade();
leftBlade.position.y = -0.7;
leftBlade.rotation.x = -Math.PI / 4;
leftArm.hand.add(leftBlade);

const rightBlade = createBlade();
rightBlade.position.y = -0.7;
rightBlade.rotation.x = -Math.PI / 4;
rightArm.hand.add(rightBlade);

// Initial placement on cliff face
kratosGroup.position.set(3, -3, 3);
kratosGroup.rotation.y = -Math.PI / 4;

// Camera setup
camera.position.set(7, 1, 7);

// Animation state
let climbHeight = -3;
let climbAngle = 0;

function animate() {
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();
    const delta = clock.getDelta();

    // Climbing progression spiral up the mountain
    climbHeight += 0.008;
    climbAngle += 0.015;

    const radius = Math.max(2.2, 3.2 - climbHeight * 0.08);
    kratosGroup.position.x = Math.cos(climbAngle) * radius;
    kratosGroup.position.z = Math.sin(climbAngle) * radius;
    kratosGroup.position.y = climbHeight;

    // Face the mountain surface
    kratosGroup.rotation.y = climbAngle + Math.PI / 2;
    kratosGroup.rotation.z = 0.15; // Lean into mountain

    // Climbing motion cycle (alternating limbs)
    const cycle = t * 3.5;
    const leftPhase = Math.sin(cycle);
    const rightPhase = Math.sin(cycle + Math.PI);

    // Arms reaching and gripping
    leftArm.root.rotation.x = leftPhase * 0.4 - 0.6;
    leftArm.root.rotation.z = 0.3 + leftPhase * 0.1;
    leftArm.forearm.rotation.x = -Math.abs(leftPhase) * 0.9 - 0.3;

    rightArm.root.rotation.x = rightPhase * 0.4 - 0.6;
    rightArm.root.rotation.z = -0.3 + rightPhase * 0.1;
    rightArm.forearm.rotation.x = -Math.abs(rightPhase) * 0.9 - 0.3;

    // Legs pushing up
    leftLeg.rotation.x = rightPhase * 0.35;
    rightLeg.rotation.x = leftPhase * 0.35;

    // Body exertion bob
    kratosGroup.position.y += Math.sin(t * 8) * 0.003;

    // Blade physics (swinging with arm movement)
    leftBlade.rotation.x = -Math.PI / 4 + Math.sin(cycle) * 0.2 + Math.cos(t * 6) * 0.1;
    rightBlade.rotation.x = -Math.PI / 4 + Math.sin(cycle + Math.PI) * 0.2 + Math.cos(t * 6 + 1) * 0.1;

    // Cape wind simulation (vertex manipulation)
    const capePos = capeGeo.attributes.position;
    for (let i = 0; i < capePos.count; i++) {
        const y = capePos.getY(i);
        if (y < 0) {
            const wave = Math.sin(y * 4 + t * 6) * 0.12 * (Math.abs(y) / 2.2);
            capePos.setZ(i, wave + 0.1);
        }
    }
    capePos.needsUpdate = true;

    // Cloud drift
    cloudsLow.rotation.y = t * 0.03;
    cloudsHigh.rotation.y = t * 0.02 + 0.5;

    // Dynamic rim light intensity (sun flaring)
    rimLight.intensity = 0.65 + Math.sin(t * 0.7) * 0.15;

    // Camera follow with cinematic framing
    const targetY = climbHeight * 0.4;
    camera.position.y += (targetY - camera.position.y) * 0.03;
    camera.lookAt(kratosGroup.position.x, climbHeight + 0.8, kratosGroup.position.z);

    controls.update();
    renderer.render(scene, camera);
}

animate();

